USE ROLE ACCOUNTADMIN;
USE WAREHOUSE DEMO_LOAD_WH;
USE SCHEMA BABY_MART_DEMO.CAMPAIGN;

DROP PROCEDURE IF EXISTS SIZE_AUDIENCE(VARIANT);
DROP PROCEDURE IF EXISTS CREATE_CAMPAIGN_DRAFT(VARIANT, VARIANT, VARCHAR);

CREATE OR REPLACE PROCEDURE SIZE_AUDIENCE(SPEC VARCHAR)
RETURNS VARCHAR
LANGUAGE JAVASCRIPT
COMMENT = 'Size an audience spec exactly as the Audience builder does: funnel, suppressions, uplift quadrants, health and composition.'
EXECUTE AS OWNER
AS
$$
"use strict";
var CMPTOOLS = (() => {
