  var SQL_NEXT_PRODUCTS = `SELECT n.NEXT_CLASS, n.BRAND_NAME, n.PRODUCT_KEY, n.SKU_CODE, n.PRODUCT_NAME, n.UNIT_RETAIL, n.PRICE_TIER, COUNT(*) AS CUSTOMERS
FROM ${S}.NEXT_BEST_PRODUCT n GROUP BY 1, 2, 3, 4, 5, 6, 7 ORDER BY 8 DESC LIMIT 30`;
  var SQL_LATEST_RUN = `SELECT * FROM ${S}.AI_RUN WHERE STAGE = ? ORDER BY GENERATED_AT DESC LIMIT 1`;
  var SQL_AI_USAGE = `SELECT STAGE, COUNT(*) AS RUNS, COUNT_IF(IS_VERIFIED) AS VERIFIED, COUNT_IF(ERROR_MESSAGE IS NOT NULL) AS FAILED,
       SUM(TOTAL_TOKENS) AS TOKENS, MAX(GENERATED_AT) AS LAST_RUN
FROM ${S}.AI_RUN GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_REPLY_SHARE_ALL = `SELECT CAMPAIGN_ID, COUNT(*) AS REPLIES, COUNT_IF(SENTIMENT IN ('negative', 'mixed')) AS NEGATIVE
FROM ${S}.VW_CUSTOMER_VOICE WHERE SOURCE = 'REPLY' AND CAMPAIGN_ID IS NOT NULL GROUP BY 1`;
  var SQL_GRIEVANCE_TREATED = `SELECT CAMPAIGN_ID, COUNT(*) AS N FROM ${S}.AUDIENCE_MEMBER
