  var checkGuardrails2 = (category, brand, start, end) => safe(() => checkGuardrails(run, category, brand, start, end));
  var estimateLift2 = (category, channels, band) => safe(() => estimateLift(run, category, channels, band));
  var createDraft2 = (brief, spec, runId) => safe(() => createDraft(run, brief, spec, runId));
  var campaignEvidence2 = (id) => safe(() => campaignEvidence(run, id));
  var testHypothesis2 = (id, dim) => safe(() => testHypothesis(run, id, dim));
  return __toCommonJS(tools_entry_exports);
})();

return CMPTOOLS.estimateLift(CATEGORY, CHANNELS, RECENCY_BAND);
$$;

CREATE OR REPLACE PROCEDURE CREATE_CAMPAIGN_DRAFT(BRIEF VARCHAR, SPEC VARCHAR, RUN_ID VARCHAR)
RETURNS VARCHAR
LANGUAGE JAVASCRIPT
COMMENT = 'Create a campaign BRIEF and a DRAFT audience from a validated spec. Never locks, approves or launches.'
EXECUTE AS OWNER
AS
$$
"use strict";
var CMPTOOLS = (() => {
  var __defProp = Object.defineProperty;
  var __getOwnPropDesc = Object.getOwnPropertyDescriptor;
  var __getOwnPropNames = Object.getOwnPropertyNames;
  var __hasOwnProp = Object.prototype.hasOwnProperty;
  var __export = (target, all) => {
    for (var name in all)
      __defProp(target, name, { get: all[name], enumerable: true });
  };
  var __copyProps = (to, from, except, desc) => {
    if (from && typeof from === "object" || typeof from === "function") {
      for (let key of __getOwnPropNames(from))
        if (!__hasOwnProp.call(to, key) && key !== except)
          __defProp(to, key, { get: () => from[key], enumerable: !(desc = __getOwnPropDesc(from, key)) || desc.enumerable });
    }
    return to;
  };
  var __toCommonJS = (mod) => __copyProps(__defProp({}, "__esModule", { value: true }), mod);

  // src/lib/campaign/tools-entry.ts
  var tools_entry_exports = {};
  __export(tools_entry_exports, {
    campaignEvidence: () => campaignEvidence2,
    checkGuardrails: () => checkGuardrails2,
    createDraft: () => createDraft2,
    estimateLift: () => estimateLift2,
    run: () => run,
    sizeAudience: () => sizeAudience2,
    testHypothesis: () => testHypothesis2
  });

  // stub:schema
  var S = "BABY_MART_DEMO.CAMPAIGN";

  // src/lib/campaign/sql.ts
  var SQL_C360 = `
SELECT f.CUSTOMER_KEY, f.CUSTOMER_ID, f.SEGMENT_NAME, f.PROFILE_STATE, f.AGE_BAND, f.LOYALTY_TIER,
       f.HOME_STORE_CODE, f.HOME_STORE_NAME, f.HOME_STATE, f.LAST_PURCHASE_DATE, f.RECENCY_DAYS, f.RECENCY_BAND,
       f.LINES_12M, f.SPEND_12M_AUD, f.AOV_AUD, f.PROMO_SHARE, f.NAPPIES_SHARE, f.FEEDING_SHARE, f.CLOTHING_SHARE,
       f.CAR_SEATS_SHARE, f.PRAMS_SHARE, f.TOP_CATEGORY, f.TOP_BRAND, f.PREFERRED_PRICE_TIER, f.RFM_SEGMENT,
       f.CHILD_STAGE, f.EST_CHILD_AGE_M, f.MULTI_CHILD_OR_GIFT, f.NAPPY_NEXT_CLASS, f.NAPPY_DUE_STATUS,
       f.CAR_SEAT_LAST_CLASS, f.CAR_SEAT_NEXT_CLASS, f.CAR_SEAT_DUE_STATUS, f.FEEDING_NEXT_CLASS, f.FEEDING_DUE_STATUS,
       f.PRAM_NO_CAR_SEAT,
       DATEDIFF('day', f.CAR_SEAT_LAST_DATE, ${S}.CMP_AS_OF()) AS CAR_SEAT_LAST_AGE_DAYS,
       ct.EMAIL_OPT_IN, ct.SMS_OPT_IN, ct.PUSH_ENABLED, ct.PREFERRED_CHANNEL, ct.IS_CONTACTABLE,
       vs.LAST_NPS, vs.LAST_NPS_CLASS, COALESCE(vs.NEG_VOICE_120D, 0) AS NEG_VOICE_120D, vs.NEG_THEME_120D,
       COALESCE(vs.HAS_OPEN_COMPLAINT, FALSE) AS HAS_OPEN_COMPLAINT, vs.STATED_INTENT,
       COALESCE(DATEDIFF('day', lc.LAST_CONTACT, ${S}.CMP_AS_OF()), 9999) AS DAYS_SINCE_CONTACT,
       COALESCE(lc.CONTACTS_30D, 0) AS CONTACTS_30D
FROM ${S}.CUSTOMER_FEATURES f
JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
LEFT JOIN ${S}.VW_CUSTOMER_VOICE_SUMMARY vs ON vs.CUSTOMER_KEY = f.CUSTOMER_KEY
LEFT JOIN (
  SELECT CUSTOMER_KEY, MAX(EVENT_DATE) AS LAST_CONTACT,
         COUNT_IF(EVENT_DATE > DATEADD('day', -30, ${S}.CMP_AS_OF())) AS CONTACTS_30D
  FROM ${S}.CAMPAIGN_EVENT WHERE EVENT_TYPE = 'SEND' AND EVENT_DATE <= ${S}.CMP_AS_OF()
  GROUP BY CUSTOMER_KEY
) lc ON lc.CUSTOMER_KEY = f.CUSTOMER_KEY`;
  var RELEVANT_EXPR = `${S}.IS_RELEVANT(${S}.CAMPAIGN_TRACK(?), CHILD_STAGE, SEGMENT_NAME, RECENCY_DAYS, NAPPY_DUE_STATUS,
  CAR_SEAT_DUE_STATUS, FEEDING_DUE_STATUS, PRAM_NO_CAR_SEAT, NAPPIES_SHARE, PRAMS_SHARE)`;
  var GRIEVANCE_EXPR = `(NEG_VOICE_120D > 0 AND NEG_THEME_120D IN ('Price and value', 'Promotions and offers'))`;
  var SQL_SETTINGS = `SELECT SETTING_KEY, SETTING_VALUE, DATA_TYPE, LABEL, DESCRIPTION, UPDATED_BY, UPDATED_AT
FROM ${S}.CMP_SETTING ORDER BY SETTING_KEY`;
  var SQL_AS_OF = `SELECT ${S}.CMP_AS_OF() AS AS_OF`;
  var SQL_OFFERS = `SELECT OFFER_ID, NAME, OFFER_TYPE, MECHANIC, DESCRIPTION, COST_PER_REDEMPTION, DISCOUNT_PCT, CATEGORY, FUNDED_BY, TERMS, IS_ACTIVE
FROM ${S}.OFFER ORDER BY TRY_TO_NUMBER(REPLACE(OFFER_ID, 'off-', ''))`;
  var SQL_CHANNELS = `SELECT CHANNEL_CODE, LABEL, COST_PER_SEND_AUD, MAX_CHARS, CONSENT_COLUMN, IS_OWNED, IS_PERSONAL, DESCRIPTION
FROM ${S}.CHANNEL ORDER BY SORT_ORDER`;
  var SQL_CAMPAIGN_METRICS = `
WITH m AS (
  SELECT CAMPAIGN_ID, COUNT_IF(GROUP_CODE = 'TREATED') AS TREATED_N, COUNT_IF(GROUP_CODE = 'HOLDOUT') AS HOLDOUT_N,
         COUNT_IF(GROUP_CODE = 'TREATED' AND COALESCE(STOCK_CONFLICT, FALSE)) AS STOCK_CONFLICT_N
  FROM ${S}.AUDIENCE_MEMBER GROUP BY CAMPAIGN_ID
), e AS (
  SELECT CAMPAIGN_ID,
         COUNT(DISTINCT IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'TREATED', CUSTOMER_KEY, NULL)) AS T_CONV,
         COUNT(DISTINCT IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'HOLDOUT', CUSTOMER_KEY, NULL)) AS H_CONV,
         SUM(IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'TREATED', ORDER_VALUE_AUD, 0)) AS T_REVENUE,
         SUM(IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'HOLDOUT', ORDER_VALUE_AUD, 0)) AS H_REVENUE,
         SUM(IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'TREATED', MARGIN_AUD, 0)) AS T_MARGIN,
         SUM(IFF(EVENT_TYPE = 'CONVERT' AND GROUP_CODE = 'HOLDOUT', MARGIN_AUD, 0)) AS H_MARGIN,
         SUM(COALESCE(OFFER_COST_AUD, 0)) AS OFFER_COST,
         SUM(COALESCE(SEND_COST_AUD, 0)) AS SEND_COST,
         COUNT_IF(EVENT_TYPE = 'SEND') AS SENDS, COUNT_IF(EVENT_TYPE = 'DELIVER') AS DELIVERED,
         COUNT_IF(EVENT_TYPE = 'BOUNCE') AS BOUNCES,
         COUNT(DISTINCT IFF(EVENT_TYPE = 'OPEN', CUSTOMER_KEY, NULL)) AS OPENERS,
         COUNT(DISTINCT IFF(EVENT_TYPE = 'CLICK', CUSTOMER_KEY, NULL)) AS CLICKERS,
         COUNT_IF(EVENT_TYPE = 'UNSUBSCRIBE') AS UNSUBS, COUNT_IF(EVENT_TYPE = 'COMPLAINT') AS COMPLAINTS,
         COUNT_IF(EVENT_TYPE = 'REPLY') AS REPLIES, MAX(EVENT_DATE) AS LAST_EVENT,
         MAX(PROVENANCE) AS EVENT_PROVENANCE
  FROM ${S}.CAMPAIGN_EVENT GROUP BY CAMPAIGN_ID
)
SELECT c.CAMPAIGN_ID, c.NAME, c.STATUS, c.OBJECTIVE, c.START_DATE, c.END_DATE, c.SIMULATED_THROUGH, c.BUDGET_AUD,
       c.CHANNELS, c.PROMOTED_CATEGORY, c.PROMOTED_CLASS, c.PROMOTED_BRAND, c.OFFER_ID, c.PROVENANCE, c.HOLDOUT_PCT,
       COALESCE(m.TREATED_N, 0) AS TREATED_N, COALESCE(m.HOLDOUT_N, 0) AS HOLDOUT_N, COALESCE(m.STOCK_CONFLICT_N, 0) AS STOCK_CONFLICT_N,
       COALESCE(e.T_CONV, 0) AS T_CONV, COALESCE(e.H_CONV, 0) AS H_CONV,
       COALESCE(e.T_REVENUE, 0) AS T_REVENUE, COALESCE(e.H_REVENUE, 0) AS H_REVENUE,
       COALESCE(e.T_MARGIN, 0) AS T_MARGIN, COALESCE(e.H_MARGIN, 0) AS H_MARGIN,
       COALESCE(e.OFFER_COST, 0) AS OFFER_COST, COALESCE(e.SEND_COST, 0) AS SEND_COST,
       COALESCE(e.SENDS, 0) AS SENDS, COALESCE(e.DELIVERED, 0) AS DELIVERED, COALESCE(e.BOUNCES, 0) AS BOUNCES,
       COALESCE(e.OPENERS, 0) AS OPENERS, COALESCE(e.CLICKERS, 0) AS CLICKERS, COALESCE(e.UNSUBS, 0) AS UNSUBS,
       COALESCE(e.COMPLAINTS, 0) AS COMPLAINTS, COALESCE(e.REPLIES, 0) AS REPLIES, e.LAST_EVENT, e.EVENT_PROVENANCE
FROM ${S}.CAMPAIGN c
LEFT JOIN m ON m.CAMPAIGN_ID = c.CAMPAIGN_ID
LEFT JOIN e ON e.CAMPAIGN_ID = c.CAMPAIGN_ID
ORDER BY COALESCE(c.START_DATE, '2099-01-01'::DATE) DESC, c.CAMPAIGN_ID`;
  var SQL_CAMPAIGN = `SELECT c.*, o.NAME AS OFFER_NAME, o.TERMS AS OFFER_TERMS, o.DESCRIPTION AS OFFER_DESCRIPTION,
       o.COST_PER_REDEMPTION AS OFFER_COST_PER_REDEMPTION
FROM ${S}.CAMPAIGN c LEFT JOIN ${S}.OFFER o ON o.OFFER_ID = c.OFFER_ID WHERE c.CAMPAIGN_ID = ?`;
  var SQL_STATUS_LOG = `SELECT FROM_STATUS, TO_STATUS, REASON, CHANGED_BY, CHANGED_AT
FROM ${S}.CAMPAIGN_STATUS_LOG WHERE CAMPAIGN_ID = ? ORDER BY CHANGED_AT, TO_STATUS`;
  var SQL_LIFT_BY = `
WITH conv AS (
  SELECT DISTINCT CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE CAMPAIGN_ID = ? AND EVENT_TYPE = 'CONVERT'
), mm AS (
  SELECT am.*, cv.CUSTOMER_KEY IS NOT NULL AS CONVERTED,
         IFF(COALESCE(am.NEG_VOICE_120D, 0) > 0 AND am.NEG_THEME IN ('Price and value', 'Promotions and offers'), 'Yes', 'No') AS GRIEVANCE
  FROM ${S}.AUDIENCE_MEMBER am LEFT JOIN conv cv ON cv.CUSTOMER_KEY = am.CUSTOMER_KEY
  WHERE am.CAMPAIGN_ID = ?
), d AS (
  SELECT 'Channel' AS DIM, CHANNEL_CODE AS VAL, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Home state', HOME_STATE, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Last purchase', RECENCY_BAND, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Segment', SEGMENT_NAME, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Child stage', CHILD_STAGE, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Loyalty tier', LOYALTY_TIER, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Needs the product', IFF(COALESCE(IS_RELEVANT, FALSE), 'Yes', 'No'), GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Home store short of promoted brand', IFF(COALESCE(STOCK_CONFLICT, FALSE), 'Yes', 'No'), GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Recent price complaint', GRIEVANCE, GROUP_CODE, CONVERTED FROM mm
  UNION ALL SELECT 'Uplift quadrant', UPLIFT_QUADRANT, GROUP_CODE, CONVERTED FROM mm WHERE UPLIFT_QUADRANT IS NOT NULL
)
SELECT DIM, COALESCE(VAL, 'Unknown') AS VAL,
       COUNT_IF(GROUP_CODE = 'TREATED') AS TN, COUNT_IF(GROUP_CODE = 'TREATED' AND CONVERTED) AS TC,
       COUNT_IF(GROUP_CODE = 'HOLDOUT') AS HN, COUNT_IF(GROUP_CODE = 'HOLDOUT' AND CONVERTED) AS HC
FROM d GROUP BY 1, 2 ORDER BY 1, 2`;
  var SQL_VARIANTS_AB = `
WITH conv AS (
  SELECT DISTINCT CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE CAMPAIGN_ID = ? AND EVENT_TYPE = 'CONVERT'
)
SELECT am.VARIANT_CODE, COUNT(*) AS N, COUNT(cv.CUSTOMER_KEY) AS CONV
FROM ${S}.AUDIENCE_MEMBER am LEFT JOIN conv cv ON cv.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE am.CAMPAIGN_ID = ? AND am.GROUP_CODE = 'TREATED' AND am.VARIANT_CODE IS NOT NULL
GROUP BY 1 ORDER BY 1`;
  var SQL_DAILY = `
WITH first_conv AS (
  SELECT CUSTOMER_KEY, GROUP_CODE, MIN(EVENT_DATE) AS D FROM ${S}.CAMPAIGN_EVENT
  WHERE CAMPAIGN_ID = ? AND EVENT_TYPE = 'CONVERT' GROUP BY 1, 2
), n AS (
  SELECT GROUP_CODE, COUNT(*) AS N FROM ${S}.AUDIENCE_MEMBER WHERE CAMPAIGN_ID = ? GROUP BY 1
), daily AS (
  SELECT D, GROUP_CODE, COUNT(*) AS CONV FROM first_conv GROUP BY 1, 2
)
SELECT d.D AS EVENT_DATE, d.GROUP_CODE,
       SUM(d.CONV) OVER (PARTITION BY d.GROUP_CODE ORDER BY d.D) / MAX(n.N) OVER (PARTITION BY d.GROUP_CODE) AS CUM_RATE
FROM daily d JOIN n ON n.GROUP_CODE = d.GROUP_CODE
ORDER BY 1, 2`;
  var SQL_REPLIES = `SELECT COALESCE(SENTIMENT, 'unread') AS SENTIMENT, COALESCE(THEME, 'Unread') AS THEME, COUNT(*) AS N
FROM ${S}.VW_CUSTOMER_VOICE WHERE CAMPAIGN_ID = ? AND SOURCE = 'REPLY' GROUP BY 1, 2 ORDER BY 3 DESC`;
  var SQL_REPLY_SAMPLES = `SELECT EVENT_DATE, STATE, STORE_NAME, VOICE_TEXT, SENTIMENT, THEME, URGENCY
FROM ${S}.VW_CUSTOMER_VOICE WHERE CAMPAIGN_ID = ? AND SOURCE = 'REPLY'
QUALIFY ROW_NUMBER() OVER (PARTITION BY VOICE_TEXT ORDER BY EVENT_DATE DESC) = 1
ORDER BY IFF(SENTIMENT = 'negative', 0, 1), EVENT_DATE DESC LIMIT 12`;
  var SQL_CONTENT = `SELECT * FROM ${S}.CONTENT_VARIANT WHERE CAMPAIGN_ID = ? ORDER BY VARIANT_CODE`;
  var SQL_CHANNEL_PLAN = `SELECT CHANNEL_CODE, MEMBERS, COST_AUD, EXP_INC_CONV, EXP_INC_MARGIN_AUD, SEND_DAY, SEND_HOUR, RATIONALE, CREATED_BY, CREATED_AT
FROM ${S}.CHANNEL_PLAN WHERE CAMPAIGN_ID = ? ORDER BY MEMBERS DESC`;
  var SQL_AUDIENCE_OF = `SELECT * FROM ${S}.AUDIENCE WHERE CAMPAIGN_ID = ? ORDER BY VERSION DESC, CREATED_AT DESC`;
  var SQL_MEMBER_SUMMARY = `SELECT GROUP_CODE, CHANNEL_CODE, COUNT(*) AS N,
       COUNT_IF(COALESCE(STOCK_CONFLICT, FALSE)) AS STOCK_CONFLICT_N, COUNT_IF(SUPPRESSED_AT IS NOT NULL) AS SUPPRESSED_N,
       COUNT_IF(UPLIFT_QUADRANT = 'PERSUADABLE') AS PERSUADABLE_N, COUNT_IF(UPLIFT_QUADRANT = 'SLEEPING_DOG') AS SLEEPING_N
FROM ${S}.AUDIENCE_MEMBER WHERE CAMPAIGN_ID = ? GROUP BY 1, 2 ORDER BY 1, 2`;
  var SQL_CAMPAIGN_STOCK = `SELECT am.HOME_STATE, COUNT(*) AS MEMBERS, COUNT_IF(COALESCE(am.STOCK_CONFLICT, FALSE)) AS SHORT_MEMBERS
FROM ${S}.AUDIENCE_MEMBER am WHERE am.CAMPAIGN_ID = ? AND am.GROUP_CODE = 'TREATED' GROUP BY 1 ORDER BY 3 DESC, 2 DESC`;
  var SQL_ALERT_LOG = `SELECT * FROM ${S}.ALERT_LOG WHERE CAMPAIGN_ID = ? ORDER BY RAISED_AT DESC`;
  var SQL_ALL_ALERT_LOG = `SELECT CAMPAIGN_ID, ALERT_CODE, STATUS, ACTION_TAKEN, ACTIONED_BY, ACTIONED_AT FROM ${S}.ALERT_LOG`;
  var SQL_OVERLAP = `
WITH me AS (SELECT START_DATE FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT c2.CAMPAIGN_ID, c2.NAME, c2.START_DATE, COUNT(*) AS SHARED_MEMBERS
FROM ${S}.AUDIENCE_MEMBER a1
JOIN ${S}.AUDIENCE_MEMBER a2 ON a2.CUSTOMER_KEY = a1.CUSTOMER_KEY AND a2.CAMPAIGN_ID <> a1.CAMPAIGN_ID AND a2.GROUP_CODE = 'TREATED'
JOIN ${S}.CAMPAIGN c2 ON c2.CAMPAIGN_ID = a2.CAMPAIGN_ID
CROSS JOIN me
WHERE a1.CAMPAIGN_ID = ? AND a1.GROUP_CODE = 'TREATED'
  AND c2.START_DATE BETWEEN DATEADD('day', -14, me.START_DATE) AND me.START_DATE
GROUP BY 1, 2, 3 ORDER BY 4 DESC`;
  var SQL_WINDOW_ANOMALIES = `
WITH c AS (SELECT START_DATE, COALESCE(SIMULATED_THROUGH, END_DATE) AS THRU FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT a.EVENT_WEEK, a.STATE, a.THEME, a.NEGATIVE_MENTIONS, ROUND(a.BASE_MEAN, 1) AS BASE_MEAN, ROUND(a.Z, 1) AS Z
FROM ${S}.VW_VOICE_THEME_ANOMALY a CROSS JOIN c
WHERE a.IS_ANOMALY AND a.EVENT_WEEK BETWEEN DATEADD('day', -14, c.START_DATE) AND c.THRU
ORDER BY a.Z DESC LIMIT 12`;
  var SQL_COMPETITOR_MOVE = `
WITH c AS (SELECT START_DATE, COALESCE(SIMULATED_THROUGH, END_DATE) AS THRU, PROMOTED_CATEGORY FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT IFF(d.CALENDAR_DATE >= c.START_DATE, 'During campaign', 'Four weeks before') AS PERIOD,
       ROUND(AVG(cp.PRICE_GAP_PCT), 2) AS AVG_GAP_PCT, COUNT(*) AS OBSERVATIONS
FROM BABY_MART_DEMO.CURATED.FACT_COMPETITOR_PRICING cp
JOIN BABY_MART_DEMO.CURATED.DIM_DATE d ON d.DATE_KEY = cp.DATE_KEY
JOIN BABY_MART_DEMO.CURATED.DIM_PRODUCT p ON p.PRODUCT_KEY = cp.PRODUCT_KEY
CROSS JOIN c
WHERE (c.PROMOTED_CATEGORY IS NULL OR p.CATEGORY = c.PROMOTED_CATEGORY)
  AND d.CALENDAR_DATE BETWEEN DATEADD('day', -28, c.START_DATE) AND c.THRU
GROUP BY 1 ORDER BY 1 DESC`;
  var SQL_MEMBER_GROUPS = `
SELECT am.RECENCY_BAND, COALESCE(am.IS_RELEVANT, FALSE) AS REL,
       (COALESCE(am.NEG_VOICE_120D, 0) > 0 AND am.NEG_THEME IN ('Price and value', 'Promotions and offers')) AS GRIEV,
       ct.EMAIL_OPT_IN, ct.SMS_OPT_IN, ct.PUSH_ENABLED, COUNT(*) AS N
FROM ${S}.AUDIENCE_MEMBER am JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE am.CAMPAIGN_ID = ?
GROUP BY 1, 2, 3, 4, 5, 6`;
  var SQL_UPLIFT_CELLS = `
WITH conv AS (
  SELECT DISTINCT CAMPAIGN_ID, CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE EVENT_TYPE = 'CONVERT' AND PROVENANCE <> 'SIMULATED'
)
SELECT am.RECENCY_BAND, COALESCE(am.IS_RELEVANT, FALSE) AS REL,
       (COALESCE(am.NEG_VOICE_120D, 0) > 0 AND am.NEG_THEME IN ('Price and value', 'Promotions and offers')) AS GRIEV,
       COUNT_IF(am.GROUP_CODE = 'TREATED') AS TN, COUNT_IF(am.GROUP_CODE = 'TREATED' AND cv.CUSTOMER_KEY IS NOT NULL) AS TC,
       COUNT_IF(am.GROUP_CODE = 'HOLDOUT') AS HN, COUNT_IF(am.GROUP_CODE = 'HOLDOUT' AND cv.CUSTOMER_KEY IS NOT NULL) AS HC
FROM ${S}.AUDIENCE_MEMBER am
JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = am.CAMPAIGN_ID AND c.PROVENANCE <> 'APP'
LEFT JOIN conv cv ON cv.CAMPAIGN_ID = am.CAMPAIGN_ID AND cv.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE c.STATUS IN ('MEASURED', 'COMPLETED', 'PAUSED', 'LIVE')
GROUP BY 1, 2, 3`;
  var SQL_CHANNEL_LIFT = `
WITH conv AS (
  SELECT DISTINCT CAMPAIGN_ID, CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE EVENT_TYPE = 'CONVERT' AND PROVENANCE <> 'SIMULATED'
)
SELECT am.CHANNEL_CODE,
       COUNT_IF(am.GROUP_CODE = 'TREATED') AS TN, COUNT_IF(am.GROUP_CODE = 'TREATED' AND cv.CUSTOMER_KEY IS NOT NULL) AS TC,
       COUNT_IF(am.GROUP_CODE = 'HOLDOUT') AS HN, COUNT_IF(am.GROUP_CODE = 'HOLDOUT' AND cv.CUSTOMER_KEY IS NOT NULL) AS HC
FROM ${S}.AUDIENCE_MEMBER am
JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = am.CAMPAIGN_ID AND c.PROVENANCE <> 'APP'
LEFT JOIN conv cv ON cv.CAMPAIGN_ID = am.CAMPAIGN_ID AND cv.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE c.STATUS IN ('MEASURED', 'COMPLETED', 'PAUSED', 'LIVE') AND am.CHANNEL_CODE IS NOT NULL
GROUP BY 1`;
  var SQL_SIGNAL_DUE = `
SELECT 'CAR_SEAT' AS TRACK, f.CAR_SEAT_LAST_CLASS AS FROM_CLASS, f.CAR_SEAT_NEXT_CLASS AS NEXT_CLASS, f.CAR_SEAT_DUE_STATUS AS DUE_STATUS,
       COUNT(*) AS CUSTOMERS, COUNT_IF(ct.IS_CONTACTABLE) AS CONTACTABLE
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.CAR_SEAT_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'NAPPY', NULL, f.NAPPY_NEXT_CLASS, f.NAPPY_DUE_STATUS, COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.NAPPY_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'FEEDING', NULL, f.FEEDING_NEXT_CLASS, f.FEEDING_DUE_STATUS, COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.FEEDING_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'GAP', 'Pram, no car seat', 'Capsule (0-6m)', 'GAP', COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.PRAM_NO_CAR_SEAT
ORDER BY 1, 2, 3, 4`;
  var SQL_SIGNAL_RFM = `SELECT RFM_SEGMENT, COUNT(*) AS CUSTOMERS, ROUND(SUM(SPEND_12M_AUD)) AS SPEND_12M_AUD, ROUND(AVG(RECENCY_DAYS)) AS AVG_RECENCY_DAYS
FROM ${S}.CUSTOMER_FEATURES GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_SIGNAL_SUPPLY = `SELECT BRAND_NAME, STATUS, COUNT(*) AS STORES, LISTAGG(DISTINCT STATE, ', ') WITHIN GROUP (ORDER BY STATE) AS STATES,
       ANY_VALUE(REASON) AS REASON, ANY_VALUE(ALERT_ID) AS ALERT_ID
FROM ${S}.SUPPLY_POSITION WHERE STATUS IN ('SHORT', 'OVER', 'LOW') GROUP BY 1, 2 ORDER BY IFF(STATUS = 'SHORT', 0, IFF(STATUS = 'OVER', 1, 2)), 3 DESC`;
  var SQL_SIGNAL_INTENT = `SELECT PURCHASE_INTENT, COUNT(*) AS MENTIONS, COUNT(DISTINCT CUSTOMER_KEY) AS CUSTOMERS
FROM ${S}.VW_CUSTOMER_VOICE
WHERE PURCHASE_INTENT IS NOT NULL AND PURCHASE_INTENT <> 'NONE' AND EVENT_DATE > DATEADD('day', -90, ${S}.CMP_AS_OF())
GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_SIGNAL_BRAND_VOICE = `SELECT BRAND_NAME, COUNT(*) AS MENTIONS,
       COUNT_IF(SENTIMENT = 'positive') AS POSITIVE, COUNT_IF(SENTIMENT IN ('negative', 'mixed')) AS NEGATIVE,
