  var SQL_OVERLAP = `
WITH me AS (SELECT START_DATE FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT c2.CAMPAIGN_ID, c2.NAME, c2.START_DATE, COUNT(*) AS SHARED_MEMBERS
FROM ${S}.AUDIENCE_MEMBER a1
JOIN ${S}.AUDIENCE_MEMBER a2 ON a2.CUSTOMER_KEY = a1.CUSTOMER_KEY AND a2.CAMPAIGN_ID <> a1.CAMPAIGN_ID AND a2.GROUP_CODE = 'TREATED'
JOIN ${S}.CAMPAIGN c2 ON c2.CAMPAIGN_ID = a2.CAMPAIGN_ID
CROSS JOIN me
WHERE a1.CAMPAIGN_ID = ? AND a1.GROUP_CODE = 'TREATED'
  AND c2.START_DATE BETWEEN DATEADD('day', -14, me.START_DATE) AND me.START_DATE
GROUP BY 1, 2, 3 ORDER BY 4 DESC`;
  var SQL_WINDOW_ANOMALIES = `
WITH c AS (SELECT START_DATE, COALESCE(SIMULATED_THROUGH, END_DATE) AS THRU FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT a.EVENT_WEEK, a.STATE, a.THEME, a.NEGATIVE_MENTIONS, ROUND(a.BASE_MEAN, 1) AS BASE_MEAN, ROUND(a.Z, 1) AS Z
FROM ${S}.VW_VOICE_THEME_ANOMALY a CROSS JOIN c
WHERE a.IS_ANOMALY AND a.EVENT_WEEK BETWEEN DATEADD('day', -14, c.START_DATE) AND c.THRU
ORDER BY a.Z DESC LIMIT 12`;
  var SQL_COMPETITOR_MOVE = `
WITH c AS (SELECT START_DATE, COALESCE(SIMULATED_THROUGH, END_DATE) AS THRU, PROMOTED_CATEGORY FROM ${S}.CAMPAIGN WHERE CAMPAIGN_ID = ?)
SELECT IFF(d.CALENDAR_DATE >= c.START_DATE, 'During campaign', 'Four weeks before') AS PERIOD,
       ROUND(AVG(cp.PRICE_GAP_PCT), 2) AS AVG_GAP_PCT, COUNT(*) AS OBSERVATIONS
FROM BABY_MART_DEMO.CURATED.FACT_COMPETITOR_PRICING cp
JOIN BABY_MART_DEMO.CURATED.DIM_DATE d ON d.DATE_KEY = cp.DATE_KEY
JOIN BABY_MART_DEMO.CURATED.DIM_PRODUCT p ON p.PRODUCT_KEY = cp.PRODUCT_KEY
CROSS JOIN c
WHERE (c.PROMOTED_CATEGORY IS NULL OR p.CATEGORY = c.PROMOTED_CATEGORY)
  AND d.CALENDAR_DATE BETWEEN DATEADD('day', -28, c.START_DATE) AND c.THRU
GROUP BY 1 ORDER BY 1 DESC`;
  var SQL_MEMBER_GROUPS = `
SELECT am.RECENCY_BAND, COALESCE(am.IS_RELEVANT, FALSE) AS REL,
       (COALESCE(am.NEG_VOICE_120D, 0) > 0 AND am.NEG_THEME IN ('Price and value', 'Promotions and offers')) AS GRIEV,
       ct.EMAIL_OPT_IN, ct.SMS_OPT_IN, ct.PUSH_ENABLED, COUNT(*) AS N
FROM ${S}.AUDIENCE_MEMBER am JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE am.CAMPAIGN_ID = ?
GROUP BY 1, 2, 3, 4, 5, 6`;
  var SQL_UPLIFT_CELLS = `
WITH conv AS (
  SELECT DISTINCT CAMPAIGN_ID, CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE EVENT_TYPE = 'CONVERT' AND PROVENANCE <> 'SIMULATED'
)
SELECT am.RECENCY_BAND, COALESCE(am.IS_RELEVANT, FALSE) AS REL,
       (COALESCE(am.NEG_VOICE_120D, 0) > 0 AND am.NEG_THEME IN ('Price and value', 'Promotions and offers')) AS GRIEV,
       COUNT_IF(am.GROUP_CODE = 'TREATED') AS TN, COUNT_IF(am.GROUP_CODE = 'TREATED' AND cv.CUSTOMER_KEY IS NOT NULL) AS TC,
       COUNT_IF(am.GROUP_CODE = 'HOLDOUT') AS HN, COUNT_IF(am.GROUP_CODE = 'HOLDOUT' AND cv.CUSTOMER_KEY IS NOT NULL) AS HC
FROM ${S}.AUDIENCE_MEMBER am
JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = am.CAMPAIGN_ID AND c.PROVENANCE <> 'APP'
LEFT JOIN conv cv ON cv.CAMPAIGN_ID = am.CAMPAIGN_ID AND cv.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE c.STATUS IN ('MEASURED', 'COMPLETED', 'PAUSED', 'LIVE')
GROUP BY 1, 2, 3`;
  var SQL_CHANNEL_LIFT = `
WITH conv AS (
  SELECT DISTINCT CAMPAIGN_ID, CUSTOMER_KEY FROM ${S}.CAMPAIGN_EVENT WHERE EVENT_TYPE = 'CONVERT' AND PROVENANCE <> 'SIMULATED'
)
SELECT am.CHANNEL_CODE,
       COUNT_IF(am.GROUP_CODE = 'TREATED') AS TN, COUNT_IF(am.GROUP_CODE = 'TREATED' AND cv.CUSTOMER_KEY IS NOT NULL) AS TC,
       COUNT_IF(am.GROUP_CODE = 'HOLDOUT') AS HN, COUNT_IF(am.GROUP_CODE = 'HOLDOUT' AND cv.CUSTOMER_KEY IS NOT NULL) AS HC
FROM ${S}.AUDIENCE_MEMBER am
JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = am.CAMPAIGN_ID AND c.PROVENANCE <> 'APP'
LEFT JOIN conv cv ON cv.CAMPAIGN_ID = am.CAMPAIGN_ID AND cv.CUSTOMER_KEY = am.CUSTOMER_KEY
WHERE c.STATUS IN ('MEASURED', 'COMPLETED', 'PAUSED', 'LIVE') AND am.CHANNEL_CODE IS NOT NULL
GROUP BY 1`;
  var SQL_SIGNAL_DUE = `
SELECT 'CAR_SEAT' AS TRACK, f.CAR_SEAT_LAST_CLASS AS FROM_CLASS, f.CAR_SEAT_NEXT_CLASS AS NEXT_CLASS, f.CAR_SEAT_DUE_STATUS AS DUE_STATUS,
       COUNT(*) AS CUSTOMERS, COUNT_IF(ct.IS_CONTACTABLE) AS CONTACTABLE
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.CAR_SEAT_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'NAPPY', NULL, f.NAPPY_NEXT_CLASS, f.NAPPY_DUE_STATUS, COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.NAPPY_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'FEEDING', NULL, f.FEEDING_NEXT_CLASS, f.FEEDING_DUE_STATUS, COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.FEEDING_DUE_STATUS IN ('DUE_NOW', 'DUE_SOON') GROUP BY 1, 2, 3, 4
UNION ALL
SELECT 'GAP', 'Pram, no car seat', 'Capsule (0-6m)', 'GAP', COUNT(*), COUNT_IF(ct.IS_CONTACTABLE)
FROM ${S}.CUSTOMER_FEATURES f JOIN ${S}.CUSTOMER_CONTACT ct ON ct.CUSTOMER_KEY = f.CUSTOMER_KEY
WHERE f.PRAM_NO_CAR_SEAT
ORDER BY 1, 2, 3, 4`;
  var SQL_SIGNAL_RFM = `SELECT RFM_SEGMENT, COUNT(*) AS CUSTOMERS, ROUND(SUM(SPEND_12M_AUD)) AS SPEND_12M_AUD, ROUND(AVG(RECENCY_DAYS)) AS AVG_RECENCY_DAYS
FROM ${S}.CUSTOMER_FEATURES GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_SIGNAL_SUPPLY = `SELECT BRAND_NAME, STATUS, COUNT(*) AS STORES, LISTAGG(DISTINCT STATE, ', ') WITHIN GROUP (ORDER BY STATE) AS STATES,
       ANY_VALUE(REASON) AS REASON, ANY_VALUE(ALERT_ID) AS ALERT_ID
FROM ${S}.SUPPLY_POSITION WHERE STATUS IN ('SHORT', 'OVER', 'LOW') GROUP BY 1, 2 ORDER BY IFF(STATUS = 'SHORT', 0, IFF(STATUS = 'OVER', 1, 2)), 3 DESC`;
  var SQL_SIGNAL_INTENT = `SELECT PURCHASE_INTENT, COUNT(*) AS MENTIONS, COUNT(DISTINCT CUSTOMER_KEY) AS CUSTOMERS
FROM ${S}.VW_CUSTOMER_VOICE
WHERE PURCHASE_INTENT IS NOT NULL AND PURCHASE_INTENT <> 'NONE' AND EVENT_DATE > DATEADD('day', -90, ${S}.CMP_AS_OF())
GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_SIGNAL_BRAND_VOICE = `SELECT BRAND_NAME, COUNT(*) AS MENTIONS,
       COUNT_IF(SENTIMENT = 'positive') AS POSITIVE, COUNT_IF(SENTIMENT IN ('negative', 'mixed')) AS NEGATIVE,
       ROUND(COUNT_IF(SENTIMENT IN ('negative', 'mixed')) / COUNT(*) * 100, 1) AS NEGATIVE_PCT,
       MODE(IFF(SENTIMENT IN ('negative', 'mixed'), THEME, NULL)) AS TOP_NEGATIVE_THEME
FROM ${S}.VW_CUSTOMER_VOICE
WHERE BRAND_NAME IS NOT NULL AND EVENT_DATE > DATEADD('day', -180, ${S}.CMP_AS_OF()) AND SOURCE <> 'REPLY'
GROUP BY 1 HAVING COUNT(*) >= 15 ORDER BY 5 DESC`;
  var SQL_SIGNAL_PRAISE = `SELECT THEME, COUNT(*) AS MENTIONS FROM ${S}.VW_CUSTOMER_VOICE
WHERE SENTIMENT = 'positive' AND EVENT_DATE > DATEADD('day', -180, ${S}.CMP_AS_OF()) AND SOURCE <> 'REPLY'
GROUP BY 1 ORDER BY 2 DESC LIMIT 6`;
  var SQL_SIGNAL_ANOMALIES = `SELECT EVENT_WEEK, STATE, THEME, NEGATIVE_MENTIONS, ROUND(BASE_MEAN, 1) AS BASE_MEAN, ROUND(Z, 1) AS Z
FROM ${S}.VW_VOICE_THEME_ANOMALY
WHERE IS_ANOMALY AND EVENT_WEEK > DATEADD('day', -42, ${S}.CMP_AS_OF()) ORDER BY EVENT_WEEK DESC, Z DESC LIMIT 10`;
  var SQL_SIGNAL_COMPETITOR = `
WITH w AS (SELECT MAX(FISCAL_YEAR * 100 + FISCAL_WEEK) AS K FROM BABY_MART_DEMO.ANALYTICS.DT_COMPETITIVE_POSITION)
SELECT CATEGORY, ROUND(AVG(AVG_PRICE_GAP_PCT), 2) AS AVG_GAP_PCT, COUNT(DISTINCT PRODUCT_KEY) AS PRODUCTS
FROM BABY_MART_DEMO.ANALYTICS.DT_COMPETITIVE_POSITION, w
WHERE FISCAL_YEAR * 100 + FISCAL_WEEK > w.K - 4
GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_IDEAS = `SELECT * FROM ${S}.IDEA ORDER BY CREATED_AT DESC, PRIORITY LIMIT 60`;
  var SQL_REJECTED_IDEAS = `SELECT TITLE, DECISION_REASON FROM ${S}.IDEA WHERE STATUS = 'REJECTED' ORDER BY DECIDED_AT DESC LIMIT 10`;
  var SQL_LEARNINGS = `SELECT l.*, c.NAME AS CAMPAIGN_NAME FROM ${S}.LEARNING l LEFT JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = l.CAMPAIGN_ID
ORDER BY l.PUBLISHED_AT DESC, ABS(l.LIFT_PP) DESC`;
  var SQL_VOICE_WEEKLY = `SELECT EVENT_WEEK, STATE, RESPONSES, PROMOTERS, DETRACTORS, NPS, BASE_NPS, VOICE_ITEMS, NEGATIVE_ITEMS,
       ROUND(AVG_SENTIMENT, 3) AS AVG_SENTIMENT, OOS_MENTIONS, PRICE_COMPLAINTS
FROM ${S}.VW_VOICE_HEALTH_WEEKLY
WHERE EVENT_WEEK > DATEADD('week', -26, ${S}.CMP_AS_OF()) AND EVENT_WEEK <= ${S}.CMP_AS_OF()
ORDER BY EVENT_WEEK, STATE`;
  var SQL_VOICE_KPI = `SELECT
  COUNT_IF(SOURCE = 'SURVEY' AND EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF())) AS RESPONSES_28D,
  ROUND(100 * (COUNT_IF(NPS_CLASS = 'PROMOTER' AND EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF()))
             - COUNT_IF(NPS_CLASS = 'DETRACTOR' AND EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF())))
        / NULLIF(COUNT_IF(SOURCE = 'SURVEY' AND EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF())), 0), 1) AS NPS_28D,
  ROUND(100 * (COUNT_IF(NPS_CLASS = 'PROMOTER' AND EVENT_DATE BETWEEN DATEADD('day', -84, ${S}.CMP_AS_OF()) AND DATEADD('day', -29, ${S}.CMP_AS_OF()))
             - COUNT_IF(NPS_CLASS = 'DETRACTOR' AND EVENT_DATE BETWEEN DATEADD('day', -84, ${S}.CMP_AS_OF()) AND DATEADD('day', -29, ${S}.CMP_AS_OF())))
        / NULLIF(COUNT_IF(SOURCE = 'SURVEY' AND EVENT_DATE BETWEEN DATEADD('day', -84, ${S}.CMP_AS_OF()) AND DATEADD('day', -29, ${S}.CMP_AS_OF())), 0), 1) AS NPS_PRIOR_8W,
  ROUND(AVG(IFF(EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF()) AND VOICE_TEXT IS NOT NULL, SENTIMENT_SCORE, NULL)), 3) AS SENTIMENT_28D,
  COUNT_IF(EVENT_DATE > DATEADD('day', -28, ${S}.CMP_AS_OF()) AND URGENCY = 'HIGH') AS HIGH_URGENCY_28D,
  COUNT(*) AS VOICE_ITEMS, COUNT_IF(IS_ENRICHED) AS ENRICHED_ITEMS, COUNT_IF(VOICE_TEXT IS NOT NULL) AS WITH_TEXT
FROM ${S}.VW_CUSTOMER_VOICE WHERE EVENT_DATE <= ${S}.CMP_AS_OF()`;
  var SQL_VOICE_ANOMALIES = `SELECT EVENT_WEEK, STATE, THEME, NEGATIVE_MENTIONS, ROUND(BASE_MEAN, 1) AS BASE_MEAN, ROUND(Z, 1) AS Z
FROM ${S}.VW_VOICE_THEME_ANOMALY WHERE IS_ANOMALY AND EVENT_WEEK > DATEADD('week', -12, ${S}.CMP_AS_OF())
ORDER BY EVENT_WEEK DESC, Z DESC LIMIT 15`;
  var SQL_VOICE_HEATMAP = `SELECT THEME, COALESCE(CUSTOMER_CHILD_STAGE, 'UNKNOWN') AS CHILD_STAGE, COUNT(*) AS N,
       COUNT_IF(SENTIMENT IN ('negative', 'mixed')) AS NEG
FROM ${S}.VW_CUSTOMER_VOICE
WHERE THEME IS NOT NULL AND THEME <> 'No comment' AND EVENT_DATE > DATEADD('day', -180, ${S}.CMP_AS_OF())
GROUP BY 1, 2`;
  var SQL_VOICE_SOURCES = `SELECT SOURCE, COUNT(*) AS N, COUNT(VOICE_TEXT) AS WITH_TEXT, MIN(EVENT_DATE) AS FIRST_DATE, MAX(EVENT_DATE) AS LAST_DATE
FROM ${S}.VW_CUSTOMER_VOICE GROUP BY 1 ORDER BY 2 DESC`;
  var SQL_ENRICH_QUALITY = `SELECT * FROM ${S}.VW_VOICE_ENRICH_QUALITY`;
  var SQL_ENRICH_COST = `SELECT COUNT(*) AS BATCHES, SUM(TEXTS_SENT) AS TEXTS, SUM(PROMPT_TOKENS) AS PROMPT_TOKENS, SUM(COMPLETION_TOKENS) AS COMPLETION_TOKENS,
       MAX(LOGGED_AT) AS LAST_RUN FROM ${S}.VOICE_ENRICH_LOG`;
  var SQL_PIPELINE = `SELECT STATUS, COUNT(*) AS N FROM ${S}.CAMPAIGN GROUP BY 1`;
  var SQL_AUDIENCES_DRAFT = `SELECT a.AUDIENCE_ID, a.NAME, a.DESCRIPTION, a.SPEC, a.VERSION, a.SOURCE, a.SIZE_AT_SAVE, a.REACHABLE_AT_SAVE, a.STATUS,
       a.CAMPAIGN_ID, c.NAME AS CAMPAIGN_NAME, a.CREATED_BY, a.CREATED_AT, a.LOCKED_AT
FROM ${S}.AUDIENCE a LEFT JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = a.CAMPAIGN_ID
WHERE a.SOURCE <> 'MODELLED' OR a.STATUS <> 'LOCKED'
ORDER BY a.CREATED_AT DESC LIMIT 50`;
  var SQL_ALL_AUDIENCES = `SELECT a.AUDIENCE_ID, a.NAME, a.DESCRIPTION, a.SPEC, a.VERSION, a.SOURCE, a.SIZE_AT_SAVE, a.REACHABLE_AT_SAVE, a.STATUS,
       a.CAMPAIGN_ID, c.NAME AS CAMPAIGN_NAME, c.STATUS AS CAMPAIGN_STATUS, a.CREATED_BY, a.CREATED_AT, a.LOCKED_AT
FROM ${S}.AUDIENCE a LEFT JOIN ${S}.CAMPAIGN c ON c.CAMPAIGN_ID = a.CAMPAIGN_ID
