  // src/lib/campaign/spec.ts
  var OPS = ["in", "not_in", "eq", "gte", "lte", "between", "is_true", "is_false"];
  function emptySpec() {
    return {
      version: 1,
      all: [],
      any: [],
      exclude: [],
      suppress: { fatigueDays: 14, priceComplainers: true, openComplaints: false, stockConflict: true },
      channels: ["EMAIL", "SMS"],
      promoted: { category: null, className: null, brand: null },
      quadrants: null,
      cap: null
    };
  }
  var SpecError = class extends Error {
  };
  var isStr = (v) => typeof v === "string";
  var isNum = (v) => typeof v === "number" && Number.isFinite(v);
  var MAX_VALUES = 40;
